WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.ViewCount, p.Score, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.CreationDate DESC NULLS FIRST) AS rn, p.OwnerUserId FROM Posts AS p WHERE p.PostTypeId = 1 AND p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR), TopUsers AS (SELECT u.Id AS UserId, u.DisplayName, u.Reputation, RANK() OVER (ORDER BY u.Reputation DESC NULLS FIRST) AS user_rank FROM Users AS u JOIN Posts AS p ON u.Id = p.OwnerUserId GROUP BY u.Id, u.DisplayName, u.Reputation HAVING COUNT(p.Id) > 5), UserBadges AS (SELECT b.UserId, COUNT(b.Id) AS BadgeCount, GROUP_CONCAT(b.Name, ', ') AS Badges FROM Badges AS b WHERE b.Class = 1 GROUP BY b.UserId) SELECT tu.UserId, tu.DisplayName, tu.Reputation, COALESCE(ub.BadgeCount, 0) AS GoldBadgeCount, COALESCE(ub.Badges, 'None') AS GoldBadges, rp.PostId, rp.Title, rp.CreationDate, rp.ViewCount, rp.Score FROM TopUsers AS tu LEFT JOIN UserBadges AS ub ON tu.UserId = ub.UserId LEFT JOIN RankedPosts AS rp ON tu.UserId = rp.OwnerUserId AND rp.rn = 1 WHERE tu.user_rank <= 10 ORDER BY tu.Reputation DESC NULLS FIRST, rp.CreationDate DESC NULLS FIRST LIMIT 20